import type { GoslingSpec } from '@gosling-lang/gosling-schema';

// The relative time coordinate system: `x.relative` re-expresses time as a signed offset from a reference
// event, and the axis labels offsets ("-4 wk", "0", "+8 wk") instead of dates.
//
// Top: flu seasons aligned to their own peak. Each season runs from ISO week 40 to week 39
// (`groupby: { period: ... }`), the anchor is the season's largest weekly count (`argmax`), and the
// season of each row is stored in the field `season` for the color. The data ends at 2015-W01, so the
// 2014/15 season is incomplete and its anchor is its largest count so far.
// Bottom: unemployment by industry aligned to a fixed event, the collapse of Lehman Brothers.
// Both views are relative, but measure from different events, so they are not linked.

const FLU = {
    url: 'https://raw.githubusercontent.com/vanessastoiber/thesis-datasets/main/5_who-flu/who_flu_usa.csv',
    type: 'csv-time',
    // the Monday of each ISO week is stored in the first field (see the period example)
    dateFields: ['ISO_YEAR', 'ISO_WEEK'],
    includesCalendarWeek: true
} as const;

const UNEMPLOYMENT = {
    type: 'json-time',
    url: 'https://raw.githubusercontent.com/vega/vega/main/docs/data/unemployment-across-industries.json',
    dateFields: ['date']
} as const;

const SERIES = ['Construction', 'Manufacturing', 'Finance', 'Information', 'Education and Health'];

const spec = {
    title: 'Do flu seasons, and industries after the 2008 crash, follow the same course?',
    subtitle: 'Flu seasons aligned to their peak week; unemployment to 15 Sep 2008. Sources: WHO FluNet; U.S. BLS',
    arrangement: 'vertical',
    views: [
        {
            tracks: [
                {
                    title: 'Influenza A, aligned to the peak of each season',
                    alignment: 'overlay',
                    data: FLU,
                    x: {
                        field: 'ISO_YEAR',
                        type: 'temporal',
                        relative: {
                            anchor: { argmax: 'INF_A' },
                            groupby: { period: { unit: 'year', weekBased: true, start: 40, newField: 'season' } },
                            unit: 'week',
                            label: "the season's peak"
                        },
                        domain: { interval: ['-16 weeks', '16 weeks'] },
                        axis: 'bottom'
                    },
                    y: {
                        field: 'INF_A',
                        type: 'quantitative',
                        domain: [0, 14000],
                        axis: 'left',
                        title: 'Cases per week'
                    },
                    color: {
                        field: 'season',
                        type: 'nominal',
                        domain: ['2009/10', '2010/11', '2011/12', '2012/13', '2013/14', '2014/15'],
                        legend: true,
                        title: 'Season'
                    },
                    tracks: [
                        { mark: 'line', size: { value: 2 } },
                        { mark: 'point', size: { value: 3 } }
                    ],
                    width: 800,
                    height: 220
                }
            ]
        },
        {
            tracks: [
                {
                    title: 'Unemployment rate, aligned to the collapse of Lehman Brothers',
                    alignment: 'overlay',
                    data: UNEMPLOYMENT,
                    dataTransform: [{ type: 'filter', field: 'series', oneOf: SERIES }],
                    x: {
                        field: 'date',
                        type: 'temporal',
                        relative: { anchor: '2008-09-15', unit: 'month', label: 'the collapse of Lehman Brothers' },
                        domain: { interval: ['-36 months', '18 months'] },
                        axis: 'bottom'
                    },
                    y: {
                        field: 'rate',
                        type: 'quantitative',
                        domain: [0, 30],
                        axis: 'left',
                        title: 'Unemployment rate (%)'
                    },
                    color: { field: 'series', type: 'nominal', domain: SERIES, legend: true, title: 'Industry' },
                    tracks: [{ mark: 'line', size: { value: 2 } }],
                    width: 800,
                    height: 200
                }
            ]
        }
    ]
};

export const EX_SPEC_TEMPORAL_RELATIVE_ALIGNMENT = spec as unknown as GoslingSpec;
import type { GoslingSpec } from '@gosling-lang/gosling-schema';

// Lives and masterpieces of 24 novelists born after 1700, from Wikidata (CC0): two SPARQL queries run on
// 2026-10-15, whose CSV exports are used unedited (time-i-gram-datasets/novelists, with the queries). A
// masterpiece is a notable work (P800) that is a literary work, has articles in at least 30 Wikipedias, and was
// first published (the earliest P577, the first edition) in the writer's lifetime or up to 10 years after.
//
// - Top: the lives in absolute time, one row per writer (Priestley's Chart of Biography; Brehmer's linear
//   chronological faceted timeline), with each masterpiece at its first edition.
// - Bottom: the same, aligned to each writer's birth (`relative.anchor: { field: "birth" }`): the axis reads ages
//   (Accurat's "From first published to masterpieces"; Brehmer's linear and radial relative faceted timelines).
//   The ring and the linear view are in the same relative coordinate system, so the ring's brush (a range of ages)
//   zooms the linear view. The lives view is in absolute time and is not linked to them.
//
// Layout notes:
// - Rows start with an empty category ('') that the header strip covers (rects fill their rows).
// - Lives and works come from two files, so each view is two tracks; only one of them draws the row labels.

const BASE = 'https://raw.githubusercontent.com/denisseram/time-i-gram-datasets/65e773b/novelists';
const WRITERS = { type: 'csv-time', url: `${BASE}/writers.csv`, interval: ['birth', 'death'] };
const WORKS = { type: 'csv-time', url: `${BASE}/works.csv`, dateFields: ['published'] };

/** The writers by birth, as in `writers.csv`, after an empty row under the header. */
const NAMES = [
    'Jane Austen',
    'Mary Shelley',
    'Honoré de Balzac',
    'Charles Dickens',
    'Charlotte Brontë',
    'Emily Brontë',
    'Herman Melville',
    'George Eliot',
    'Fyodor Dostoyevsky',
    'Gustave Flaubert',
    'Jules Verne',
    'Leo Tolstoy',
    'Mark Twain',
    'Thomas Hardy',
    'Marcel Proust',
    'Thomas Mann',
    'Virginia Woolf',
    'James Joyce',
    'Franz Kafka',
    'F. Scott Fitzgerald',
    'William Faulkner',
    'Ernest Hemingway',
    'Gabriel García Márquez',
    'Toni Morrison'
];
const ROW = { field: 'writerLabel', type: 'nominal', domain: ['', ...NAMES] } as const;

const LIFE_COLOR = '#d9d4c7';
const WORK_COLOR = '#8c2d04';

/** Works: the dot size is the number of Wikipedias with an article about the work. */
const workMarks = {
    mark: 'point',
    color: { value: WORK_COLOR },
    size: { field: 'sitelinks', type: 'quantitative', domain: [30, 110], range: [2, 7] },
    opacity: { value: 0.85 },
    tooltip: [
        { field: 'workLabel', type: 'nominal', alt: 'Work' },
        { field: 'writerLabel', type: 'nominal', alt: 'Writer' },
        { field: 'published', type: 'temporal', alt: 'First published', format: '%Y' },
        { field: 'sitelinks', type: 'quantitative', alt: 'Wikipedias' }
    ]
};

/** Each writer's age: offsets from their own birth, in years. */
const AGE = {
    type: 'temporal',
    relative: { anchor: { field: 'birth' }, unit: 'year', label: 'birth' },
    domain: { interval: ['0 years', '90 years'] },
    linkingId: 'age'
} as const;

const spec = {
    title: 'When did each novelist publish their masterpieces, and at what age?',
    subtitle:
        'Lives (bars) and works with articles in 30+ Wikipedias (dots, larger: in more). Source: Wikidata (CC0), queried 15 October 2026',
    arrangement: 'vertical',
    spacing: 40,
    views: [
        {
            xDomain: { interval: ['1770', '2025'] },
            tracks: [
                {
                    title: 'Lives and first editions, by year',
                    alignment: 'overlay',
                    x: { field: 'birth', type: 'temporal', axis: 'bottom' },
                    row: ROW,
                    tracks: [
                        {
                            data: WRITERS,
                            mark: 'rect',
                            xe: { field: 'death', type: 'temporal' },
                            row: { ...ROW, legend: true },
                            color: { value: LIFE_COLOR },
                            tooltip: [
                                { field: 'writerLabel', type: 'nominal', alt: 'Writer' },
                                { field: 'birth', type: 'temporal', alt: 'Born' },
                                { field: 'death', type: 'temporal', alt: 'Died' }
                            ]
                        },
                        { ...workMarks, data: WORKS, x: { field: 'published', type: 'temporal', axis: 'bottom' } }
                    ],
                    width: 1300,
                    height: 500
                }
            ]
        },
        {
            arrangement: 'horizontal',
            spacing: 40,
            views: [
                {
                    layout: 'circular',
                    centerRadius: 0.3,
                    tracks: [
                        {
                            title: 'Ages, one ring per writer (outer: Austen)',
                            alignment: 'overlay',
                            x: { ...AGE, field: 'birth', axis: 'top', linkingId: undefined },
                            row: ROW,
                            tracks: [
                                {
                                    data: WRITERS,
                                    mark: 'rect',
                                    xe: { field: 'death', type: 'temporal' },
                                    color: { value: LIFE_COLOR }
                                },
                                {
                                    ...workMarks,
                                    data: WORKS,
                                    x: { ...AGE, field: 'published', axis: 'top', linkingId: undefined },
                                    size: { ...workMarks.size, range: [1, 4] }
                                },
                                {
                                    data: WRITERS,
                                    mark: 'brush',
                                    x: { linkingId: 'age' },
                                    color: { value: 'steelBlue' },
                                    opacity: { value: 0.15 }
                                }
                            ],
                            width: 460,
                            height: 200
                        }
                    ]
                },
                {
                    tracks: [
                        {
                            title: 'Ages: lives and first editions, aligned to each birth',
                            alignment: 'overlay',
                            x: { ...AGE, field: 'birth', axis: 'bottom', domain: { interval: ['15 years', '60 years'] } },
                            row: ROW,
                            tracks: [
                                {
                                    data: WRITERS,
                                    mark: 'rect',
                                    xe: { field: 'death', type: 'temporal' },
                                    row: { ...ROW, legend: true },
                                    color: { value: LIFE_COLOR }
                                },
                                {
                                    ...workMarks,
                                    data: WORKS,
                                    x: { ...AGE, field: 'published', axis: 'bottom', domain: { interval: ['15 years', '60 years'] } }
                                }
                            ],
                            width: 800,
                            height: 500
                        }
                    ]
                }
            ]
        }
    ]
};

export const EX_SPEC_TEMPORAL_NOVELISTS = spec as unknown as GoslingSpec;
import type { GoslingSpec } from '@gosling-lang/gosling-schema';

// NASA C-MAPSS FD001: 100 simulated turbofan engines run from a healthy state to failure (Saxena et al., PHM08).
// The data count operational cycles, not dates: the preprocessed CSV gives every engine a synthetic clock
// (2000-01-01 + 1 day per cycle), so offsets in days are cycles, and the axis says so (`relative.unitName`).
// `hi_smooth` is a health index (mean z-score of 12 sensors against the engine's first 30 cycles, up = worse).
//
// The two views differ only in the anchor of `x.relative`. Top: each engine from its own first cycle
// (`anchor: "first"`, `groupby: "unit"`); the engines fail at different ages, so the curves fan out. Bottom:
// each engine up to its own last cycle (`anchor: "last"`), the failure; the curves collapse onto one course.
// In both, `timeUnit: "week"` with `aggregate: "mean"` bins the offsets into whole weeks from the anchor and
// draws the fleet's mean. Both views are relative, but to different events, so they are not linked.

const FD001 = {
    type: 'csv-time',
    url: 'https://raw.githubusercontent.com/denisseram/time-i-gram-datasets/6b38e3d/cmapss/fd001_train.csv',
    dateFields: ['date']
} as const;

/** The shortest-, median- and longest-lived engines, named in a field of their own: a legend shows every
 * category of its field across the members of an overlay, so it cannot reuse `unit` (100 grey lines). */
const HIGHLIGHT = [
    { from: '39', to: 'Shortest life (128)' },
    { from: '68', to: 'Median (199)' },
    { from: '69', to: 'Longest (362)' }
];
const HIGHLIGHT_COLOR = {
    field: 'engine',
    type: 'nominal',
    domain: HIGHLIGHT.map(h => h.to),
    range: ['#e15759', '#f28e2b', '#4e79a7'],
    legend: true,
    title: 'Engine'
} as const;

const Y = {
    field: 'hi_smooth',
    type: 'quantitative',
    domain: [-1, 7.5],
    axis: 'left',
    title: 'Health index (z, up = worse)'
} as const;

function view(anchor: 'first' | 'last', title: string, label: string, interval: [string, string]) {
    const x = {
        field: 'date',
        type: 'temporal',
        relative: { anchor, groupby: 'unit', unit: 'day', unitName: 'cycle', label },
        domain: { interval },
        axis: 'bottom'
    } as const;
    return {
        tracks: [
            {
                title,
                alignment: 'overlay',
                data: FD001,
                x,
                y: Y,
                tracks: [
                    {
                        // one line per engine: the color channel separates the lines, all drawn in one grey
                        mark: 'line',
                        color: { field: 'unit', type: 'nominal', range: ['#9aa5b1'] },
                        opacity: { value: 0.35 },
                        size: { value: 1 }
                    },
                    {
                        mark: 'line',
                        dataTransform: [
                            { type: 'filter', field: 'unit', oneOf: HIGHLIGHT.map(h => h.from) },
                            { type: 'replace', field: 'unit', newField: 'engine', replace: HIGHLIGHT }
                        ],
                        color: HIGHLIGHT_COLOR,
                        size: { value: 2 }
                    },
                    {
                        mark: 'line',
                        x: { ...x, timeUnit: 'week' },
                        y: { ...Y, aggregate: 'mean' },
                        color: { value: '#1b1f24' },
                        size: { value: 3 },
                        style: { legendLabel: 'Fleet mean' }
                    }
                ],
                width: 800,
                height: 240
            }
        ]
    };
}

const spec = {
    title: 'When do jet engines wear out? It depends on what you align them to',
    subtitle: 'NASA C-MAPSS FD001 (Saxena et al. 2008): 100 simulated engines run to failure',
    arrangement: 'vertical',
    views: [
        view('first', 'Aligned to the first cycle: the engines fail at different ages', 'entry into service', [
            '0 days',
            '370 days'
        ]),
        view('last', 'Aligned to the failure: degradation follows one course', 'failure', ['-370 days', '0 days'])
    ]
};

export const EX_SPEC_TEMPORAL_CMAPSS_ALIGNMENT = spec as unknown as GoslingSpec;
